param([switch]$PreviewOnly)
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing

$source = @'
using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;

public static class Lot5Image {
  static Bitmap Blank(int w,int h,Color c) { var b=new Bitmap(w,h,PixelFormat.Format32bppArgb); using(var g=Graphics.FromImage(b)){g.Clear(c);} return b; }
  static Bitmap Read(string p) { using(var src=(Bitmap)Image.FromFile(p)){ var b=new Bitmap(src.Width,src.Height,PixelFormat.Format32bppArgb); using(var g=Graphics.FromImage(b)){g.DrawImage(src,0,0,src.Width,src.Height);} return b; } }
  static void Draw(Bitmap dst,Bitmap src,Rectangle sr,Rectangle dr) { using(var g=Graphics.FromImage(dst)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.PixelOffsetMode=PixelOffsetMode.HighQuality;g.DrawImage(src,dr,sr,GraphicsUnit.Pixel);} }
  static byte[] Bytes(Bitmap b) { var d=b.LockBits(new Rectangle(0,0,b.Width,b.Height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb); var a=new byte[b.Width*b.Height*4]; for(int y=0;y<b.Height;y++) Marshal.Copy(IntPtr.Add(d.Scan0,y*d.Stride),a,y*b.Width*4,b.Width*4); b.UnlockBits(d); return a; }
  static void Put(Bitmap b,byte[] a) { var d=b.LockBits(new Rectangle(0,0,b.Width,b.Height),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb); for(int y=0;y<b.Height;y++) Marshal.Copy(a,y*b.Width*4,IntPtr.Add(d.Scan0,y*d.Stride),b.Width*4); b.UnlockBits(d); }
  static byte Clamp(double x) { return (byte)Math.Max(0,Math.Min(255,Math.Round(x))); }
  static Bitmap Cover(string p,int w,int h) { using(var s=Read(p)){double sc=Math.Max((double)w/s.Width,(double)h/s.Height);int cw=(int)Math.Round(w/sc),ch=(int)Math.Round(h/sc);int sx=(s.Width-cw)/2,sy=(s.Height-ch)/2;var o=Blank(w,h,Color.Transparent);Draw(o,s,new Rectangle(sx,sy,cw,ch),new Rectangle(0,0,w,h));return o;} }
  static Bitmap Strip(string p,int w,int h,int keyR,int keyG,int keyB,bool ceiling) { using(var s=Read(p)){var o=Blank(w,h,Color.Transparent); if(ceiling){int top=0; while(top<s.Height && RowBg(s,top,keyR,keyG,keyB))top++;int bottom=s.Height-1;while(bottom>top&&RowBg(s,bottom,keyR,keyG,keyB))bottom--;int split=top+(bottom-top)*77/100;Draw(o,s,new Rectangle(0,top,s.Width,split-top),new Rectangle(0,0,w,100));Draw(o,s,new Rectangle(0,split,s.Width,bottom-split+1),new Rectangle(0,100,w,20));}else{int top=0;while(top<s.Height && RowBg(s,top,keyR,keyG,keyB))top++;Draw(o,s,new Rectangle(0,top,s.Width,s.Height-top),new Rectangle(0,6,w,h-6));}return Key(o,keyR,keyG,keyB);}}
  static bool RowKey(Bitmap b,int y,int r,int g,int bl){int n=0;for(int x=0;x<b.Width;x++){var c=b.GetPixel(x,y);if(Math.Abs(c.R-r)<15&&Math.Abs(c.G-g)<15&&Math.Abs(c.B-bl)<15)n++;}return n>b.Width*0.85;}
  static bool RowBlack(Bitmap b,int y){int n=0;for(int x=0;x<b.Width;x++){var c=b.GetPixel(x,y);if(c.R<4&&c.G<4&&c.B<4)n++;}return n>b.Width*0.75;}
  static bool RowBg(Bitmap b,int y,int r,int g,int bl){return RowBlack(b,y)||RowKey(b,y,r,g,bl);}
  static Bitmap Key(Bitmap b,int kr,int kg,int kb){var a=Bytes(b);for(int i=0;i<a.Length;i+=4){if(a[i+3]==0)continue;double db=a[i]-kb,dg=a[i+1]-kg,dr=a[i+2]-kr,d=Math.Sqrt(db*db+dg*dg+dr*dr);int al=(int)Math.Round(Math.Max(0,Math.Min(255,(d-14)*255/40)));if(d<14)al=0;if(al>0&&al<255){if(kg==255&&kg>kr+80&&kg>kb+80)a[i+1]=(byte)Math.Min(a[i+1],Math.Max(a[i],a[i+2])+8);if(kr==255&&kb==255&&kr>kg+80){a[i+2]=(byte)Math.Min(a[i+2],a[i+1]+8);a[i]=(byte)Math.Min(a[i],a[i+1]+8);}}a[i+3]=(byte)al;}Put(b,a);return b;}
  static void Grade(Bitmap b,double sat,double lum){var a=Bytes(b);for(int i=0;i<a.Length;i+=4){double gray=.299*a[i+2]+.587*a[i+1]+.114*a[i];for(int k=0;k<3;k++){double v=gray+(a[i+k]-gray)*sat; a[i+k]=Clamp(v*lum);} }Put(b,a);}
  static void Tile(Bitmap b,int band){var a=Bytes(b);int w=b.Width,h=b.Height;for(int x=0;x<band;x++){double t=(double)x/(band-1);int rx=w-1-x;for(int y=0;y<h;y++)for(int c=0;c<4;c++){int i=(y*w+x)*4+c,j=(y*w+rx)*4+c;double m=(a[i]+a[j])/2.0;a[i]=Clamp(m*(1-t)+a[i]*t);a[j]=Clamp(m*(1-t)+a[j]*t);}}Put(b,a);}
  static void CleanKey(Bitmap b,int kr,int kg,int kb){var a=Bytes(b);for(int i=0;i<a.Length;i+=4){if(a[i+3]==0)continue;int B=a[i],G=a[i+1],R=a[i+2];double d=Math.Sqrt((B-kb)*(B-kb)+(G-kg)*(G-kg)+(R-kr)*(R-kr));if(d<24){a[i+3]=0;continue;}if(kg==255&&G>R+15&&G>B+15)a[i+1]=(byte)Math.Min(G,Math.Max(R,B)+6);if(kr==255&&kb==255&&R>G+15&&B>G+15){a[i]=(byte)Math.Min(R,G+6);a[i+2]=(byte)Math.Min(B,G+6);}}Put(b,a);}
  static void ClipBottom(Bitmap b,int bottom){for(int y=bottom+1;y<b.Height;y++)for(int x=0;x<b.Width;x++)b.SetPixel(x,y,Color.Transparent);}
  static void ClipTop(Bitmap b,int top){for(int y=0;y<top;y++)for(int x=0;x<b.Width;x++)b.SetPixel(x,y,Color.Transparent);}
  static void FillCeiling(Bitmap b){for(int x=0;x<b.Width;x++){bool any=false;for(int y=0;y<b.Height;y++)if(b.GetPixel(x,y).A>200){any=true;break;}if(!any){int bx=-1,dist=999;for(int xx=0;xx<b.Width;xx++){for(int y=0;y<=100;y++)if(b.GetPixel(xx,y).A>200){int d=Math.Abs(xx-x);if(d<dist){bx=xx;dist=d;}break;}}if(bx>=0)for(int y=0;y<=100;y++){var n=b.GetPixel(bx,y);b.SetPixel(x,y,Color.FromArgb(255,n.R,n.G,n.B));}}for(int y=0;y<=100;y++){var c=b.GetPixel(x,y);if(c.A>40)continue;int best=-1,dist=999;for(int yy=0;yy<b.Height;yy++){var n=b.GetPixel(x,yy);if(n.A>200&&Math.Abs(yy-y)<dist){best=yy;dist=Math.Abs(yy-y);}}if(best>=0){var n=b.GetPixel(x,best);b.SetPixel(x,y,Color.FromArgb(255,n.R,n.G,n.B));}}}}
  static void FillFloor(Bitmap b){for(int x=0;x<b.Width;x++){int top=-1;for(int y=0;y<b.Height;y++)if(b.GetPixel(x,y).A>8){top=y;break;}if(top<0)continue;Color last=b.GetPixel(x,top);for(int y=top;y<b.Height;y++){Color c=b.GetPixel(x,y);if(c.A>40)last=c;else b.SetPixel(x,y,Color.FromArgb(255,last.R,last.G,last.B));}}}
  static void Opaque(Bitmap b){var a=Bytes(b);for(int i=3;i<a.Length;i+=4)a[i]=255;Put(b,a);}
  static void SmoothBand(Bitmap b,int y0,int y1,int radius){var src=Bytes(b);var dst=(byte[])src.Clone();int w=b.Width;for(int y=y0;y<=y1;y++)for(int x=0;x<w;x++){double r=0,g=0,bl=0;int n=0;for(int dx=-radius;dx<=radius;dx++){int xx=(x+dx+w)%w;int i=(y*w+xx)*4;bl+=src[i];g+=src[i+1];r+=src[i+2];n++;}int o=(y*w+x)*4;dst[o]=Clamp(bl/n);dst[o+1]=Clamp(g/n);dst[o+2]=Clamp(r/n);dst[o+3]=255;}Put(b,dst);}
  public static void MakeThunderCeiling(string raw,string output){var b=Strip(raw,1920,120,0,255,0,true);Grade(b,.38,.80);Tile(b,160);CleanKey(b,0,255,0);FillCeiling(b);Tile(b,160);CleanKey(b,0,255,0);FillCeiling(b);SmoothBand(b,75,100,8);for(int y=101;y<120;y++)for(int x=0;x<1920;x++)b.SetPixel(x,y,Color.Transparent);using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.None;int[] centers={120,205,295,560,790,875,1160,1245,1330,1570,1770,1830};int[] lengths={19,18,17,2,19,18,19,16,19,2,19,15};int[] widths={72,68,70,60,70,68,72,64,68,58,66,62};for(int i=0;i<lengths.Length;i++){int cx=centers[i],w=widths[i],tip=100+lengths[i];PointF[] outer={new PointF(cx-w/2,100),new PointF(cx+w/2,100),new PointF(cx+w*.34f,100+lengths[i]*.40f),new PointF(cx+4,tip-2),new PointF(cx,tip),new PointF(cx-3,tip-3),new PointF(cx-w*.28f,100+lengths[i]*.46f)};g.FillPolygon(new SolidBrush(Color.FromArgb(255,31,42,57)),outer);PointF[] face={new PointF(cx-2,101),new PointF(cx+w*.22f,101),new PointF(cx+2,tip-3),new PointF(cx-1,tip-2)};g.FillPolygon(new SolidBrush(Color.FromArgb(255,53,70,91)),face);PointF[] side={new PointF(cx-w*.28f,101),new PointF(cx-2,101),new PointF(cx-1,tip-2),new PointF(cx-3,tip-3)};g.FillPolygon(new SolidBrush(Color.FromArgb(255,39,52,69)),side);}}b.Save(output,ImageFormat.Png);b.Dispose();}
  public static void DespillEdge(string p,bool magenta){using(var b=Read(p)){int w=b.Width,h=b.Height;var a=Bytes(b);var src=(byte[])a.Clone();for(int y=0;y<h;y++)for(int x=0;x<w;x++){int i=(y*w+x)*4;if(src[i+3]<=40)continue;bool edge=false;for(int yy=Math.Max(0,y-3);yy<=Math.Min(h-1,y+3)&&!edge;yy++)for(int xx=Math.Max(0,x-3);xx<=Math.Min(w-1,x+3);xx++)if(src[(yy*w+xx)*4+3]<=8){edge=true;break;}if(!edge)continue;int blue=a[i],green=a[i+1],red=a[i+2];if(magenta&&red>green+8&&blue>green+8){a[i]= (byte)Math.Min(blue,green);a[i+2]=(byte)Math.Min(red,green);}else if(!magenta&&green>red+8&&green>blue+8)a[i+1]=(byte)Math.Min(green,Math.Max(red,blue));}Put(b,a);b.Save(p,ImageFormat.Png);}} 
  public static string EdgeTint(string p,bool magenta){using(var b=Read(p)){int n=0,bad=0;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){Color c=b.GetPixel(x,y);if(c.A<=40)continue;bool edge=false;for(int yy=Math.Max(0,y-3);yy<=Math.Min(b.Height-1,y+3)&&!edge;yy++)for(int xx=Math.Max(0,x-3);xx<=Math.Min(b.Width-1,x+3);xx++)if(b.GetPixel(xx,yy).A<=8){edge=true;break;}if(!edge)continue;n++;if(magenta?(c.R>c.G+8&&c.B>c.G+8):(c.G>c.R+8&&c.G>c.B+8))bad++;}return String.Format(System.Globalization.CultureInfo.InvariantCulture,"{0} key-tinted solid pixels in 3px edge ring: {1:P2} ({2}/{3})",System.IO.Path.GetFileName(p),(double)bad/Math.Max(1,n),bad,n);}}
  static void Dilate(Bitmap b,int radius){var a=Bytes(b);var src=(byte[])a.Clone();int w=b.Width,h=b.Height;for(int y=0;y<h;y++)for(int x=0;x<w;x++){int i=(y*w+x)*4;if(src[i+3]>8)continue;int best=-1;for(int yy=Math.Max(0,y-radius);yy<=Math.Min(h-1,y+radius)&&best<0;yy++)for(int xx=Math.Max(0,x-radius);xx<=Math.Min(w-1,x+radius);xx++){int j=(yy*w+xx)*4;if(src[j+3]>40){best=j;break;}}if(best>=0){a[i]=src[best];a[i+1]=src[best+1];a[i+2]=src[best+2];a[i+3]=255;}}Put(b,a);}
  public static void Process(string root,string name,string raw,string type){Bitmap b;int kr=type.Contains("wind")?255:0,kg=type.Contains("wind")?0:255,kb=type.Contains("wind")?255:0;if(type=="farwind"||type=="farthunder"){b=Cover(raw,1920,1080);Grade(b,.42,type=="farwind"?.83:.82);Tile(b,160);Opaque(b);}else if(type=="midwind"){b=Key(Cover(raw,1920,1080),kr,kg,kb);Grade(b,.42,.82);for(int y=0;y<1080;y++)for(int x=0;x<60;x++){b.SetPixel(x,y,Color.Transparent);b.SetPixel(1919-x,y,Color.Transparent);}Tile(b,160);ClipBottom(b,900);ClipTop(b,120);}else if(type=="midthunder"){b=Key(Cover(raw,1920,1080),kr,kg,kb);Grade(b,.42,.82);for(int y=0;y<1080;y++)for(int x=0;x<60;x++){b.SetPixel(x,y,Color.Transparent);b.SetPixel(1919-x,y,Color.Transparent);}Tile(b,160);ClipBottom(b,900);Dilate(b,7);ClipBottom(b,900);for(int y=0;y<1080;y++)for(int x=0;x<60;x++){b.SetPixel(x,y,Color.Transparent);b.SetPixel(1919-x,y,Color.Transparent);}}else if(type=="floorwind"){b=Strip(raw,1920,200,kr,kg,kb,false);Grade(b,.40,.84);Tile(b,160);}else if(type=="floorthunder"){b=Strip(raw,1920,200,kr,kg,kb,false);Grade(b,.40,.82);Tile(b,160);}else if(type=="ceilingwind"){b=Strip(raw,1920,120,kr,kg,kb,true);Grade(b,.40,.82);Tile(b,160);}else{b=Strip(raw,1920,120,kr,kg,kb,true);Grade(b,.38,.80);Tile(b,160);}if(!type.Contains("far"))CleanKey(b,kr,kg,kb);if(type.StartsWith("floor"))FillFloor(b);if(type.StartsWith("ceiling")){FillCeiling(b);Tile(b,160);CleanKey(b,kr,kg,kb);FillCeiling(b);Tile(b,160);CleanKey(b,kr,kg,kb);FillCeiling(b);}b.Save(System.IO.Path.Combine(root,name+".png"),ImageFormat.Png);b.Dispose();}
  public static string Stats(string p,int kr,int kg,int kb){using(var b=Read(p)){int w=b.Width,h=b.Height;var a=Bytes(b);long key=0,solid=0,haze=0,bright=0,brightPurple=0,brightYellow=0,wind=0;double ysum=0,satsum=0;int p99idx=(int)(w*h*.99);var ys=new int[w*h];int n=0,minx=w,miny=h,maxx=-1,maxy=-1;for(int yy=0;yy<h;yy++)for(int x=0;x<w;x++){int i=(yy*w+x)*4,A=a[i+3],B=a[i],G=a[i+1],R=a[i+2];if(A>0&&Math.Sqrt((R-kr)*(R-kr)+(G-kg)*(G-kg)+(B-kb)*(B-kb))<8)key++;if(A>8){if(x<minx)minx=x;if(x>maxx)maxx=x;if(yy<miny)miny=yy;if(yy>maxy)maxy=yy;}if(A>40){solid++;double Y=.299*R+.587*G+.114*B;ys[n++]=(int)Y;ysum+=Y;double mx=Math.Max(R,Math.Max(G,B)),mn=Math.Min(R,Math.Min(G,B));satsum+=mx==0?0:(mx-mn)/mx;if(Y>190)bright++;if(G>200&&B>170)wind++;double hue=Hue(R,G,B);if(hue>=255&&hue<=295&&mx/255.0>.6&&(mx-mn)/Math.Max(1,mx)>.35)brightPurple++;if(R>200&&G>180&&B<120)brightYellow++;}if(A>=9&&A<=40)haze++;}Array.Sort(ys,0,n);double mean=n>0?ysum/n:0,sat=n>0?satsum/n:0;double p99=n>0?ys[Math.Min(n-1,(int)(n*.99))]:0;double edge=0,near=0;for(int y=0;y<h;y++)for(int c=0;c<4;c++){int l=(y*w)*4+c,r=(y*w+w-1)*4+c;edge+=Math.Abs(a[l]-a[r]);if(w>1){near+=Math.Abs(a[l]-a[l+4]);near+=Math.Abs(a[r]-a[r-4]);}}double ratio=edge/Math.Max(1,near/2);return String.Format(System.Globalization.CultureInfo.InvariantCulture,"{0} {1}x{2} bbox={3},{4}..{5},{6} key={7} alpha>40={8} haze9-40={9:P3} Ymean={10:F2} Yp99={11:F2} Ymax={12} satMean={13:F4} windBright={14:P4} purpleBright={15:P4} yellowBright={16:P4} seamRatio={17:F4}",System.IO.Path.GetFileName(p),w,h,minx,miny,maxx,maxy,key,n,(double)haze/(w*h),mean,p99,n>0?ys[n-1]:0,sat,(double)wind/Math.Max(1,n),(double)brightPurple/Math.Max(1,n),(double)brightYellow/Math.Max(1,n),ratio);}}
  public static string Structure(string p,string type){using(var b=Read(p)){int w=b.Width,h=b.Height;if(type.StartsWith("floor")){int[] tops=new int[w];int lo=h,hi=-1,continuous=0;for(int x=0;x<w;x++){int t=-1;for(int y=0;y<h;y++)if(b.GetPixel(x,y).A>8){t=y;break;}tops[x]=t;if(t>=0){lo=Math.Min(lo,t);hi=Math.Max(hi,t);bool ok=true;for(int y=t;y<h;y++)if(b.GetPixel(x,y).A<=8){ok=false;break;}if(ok)continuous++;}}Array.Sort(tops);return String.Format("floor yTop min={0} max={1} median={2} continuous={3:P2}",lo,hi,tops[w/2],(double)continuous/w);}if(type.StartsWith("ceiling")){int holes=0,lastMax=-1,with=0,columns105=0;double sum=0,sum2=0;int maxRow=0;for(int x=0;x<w;x++){bool full=true;int last=-1;for(int y=0;y<h;y++)if(b.GetPixel(x,y).A>40)last=y;for(int y=0;y<=100;y++)if(b.GetPixel(x,y).A<=40)full=false;if(!full)holes++;lastMax=Math.Max(lastMax,last);if(last>104)with++;bool in105=false;for(int y=105;y<=118;y++)if(b.GetPixel(x,y).A>40)in105=true;if(in105)columns105++;sum+=last;sum2+=(double)last*last;}for(int y=101;y<=119;y++){int count=0;for(int x=0;x<w;x++)if(b.GetPixel(x,y).A>40)count++;maxRow=Math.Max(maxRow,count);}double sd=Math.Sqrt(Math.Max(0,sum2/w-(sum/w)*(sum/w)));return String.Format("ceiling holes0-100={0} row101-119 max={1:P2} columns105-118={2:P2} lastYStd={3:F2}px maxLast={4} columnsTip>104={5:P2}",holes,(double)maxRow/w,(double)columns105/w,sd,lastMax,(double)with/w);}int edge=0;for(int y=0;y<h;y++)for(int x=0;x<60;x++)if(b.GetPixel(x,y).A!=0||b.GetPixel(1919-x,y).A!=0)edge++;double trans=0,center=0;for(int y=0;y<h;y++)for(int x=0;x<w;x++){int a=b.GetPixel(x,y).A;if(a<=8)trans++;if(y>=420&&y<=620&&a>40)center++;}int maxRun=0;for(int y=620;y<=900;y++){int run=0;for(int x=0;x<w;x++){if(b.GetPixel(x,y).A>40){run++;maxRun=Math.Max(maxRun,run);}else run=0;}}return String.Format("mid transparent={0:P2} edgeAlphaPixels={1} centralSolid={2:P3} lowerMaxRun={3}px",trans/(w*h),edge,center/(w*201),maxRun);}}
  public static int AlphaMin(string p){using(var b=Read(p)){int min=255;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)min=Math.Min(min,b.GetPixel(x,y).A);return min;}}
  static double Hue(int r,int g,int b){double mx=Math.Max(r,Math.Max(g,b)),mn=Math.Min(r,Math.Min(g,b)),d=mx-mn;if(d==0)return 0;double h=mx==r?60*((g-b)/d%6):mx==g?60*((b-r)/d+2):60*((r-g)/d+4);if(h<0)h+=360;return h;}
}
'@
Add-Type -TypeDefinition $source -ReferencedAssemblies System.Drawing
$root = (Resolve-Path '.').Path
$raw = Join-Path $root 'art_review/jet/lot5/raw'
$out = Join-Path $root 'art_review/jet/lot5'
$preview = Join-Path $out '_preview'
$jobs = @(
  @('jet_bg_wind_far','wind_far','farwind'),@('jet_bg_wind_mid','wind_mid','midwind'),@('jet_floor_wind','wind_floor','floorwind'),@('jet_ceiling_wind','wind_ceiling','ceilingwind'),
  @('jet_bg_thunder_far','thunder_far','farthunder'),@('jet_bg_thunder_mid','thunder_mid','midthunder'),@('jet_floor_thunder','thunder_floor','floorthunder'),@('jet_ceiling_thunder','thunder_ceiling','ceilingthunder')
)
if(-not $PreviewOnly){
  foreach($j in $jobs){[Lot5Image]::Process($out,$j[0],(Join-Path $raw ($j[1]+'.png')),$j[2])}
  [Lot5Image]::MakeThunderCeiling((Join-Path $raw 'thunder_ceiling.png'),(Join-Path $out 'jet_ceiling_thunder.png'))
  foreach($entry in @(@('jet_bg_wind_mid.png',$true),@('jet_ceiling_wind.png',$true),@('jet_bg_thunder_mid.png',$false),@('jet_ceiling_thunder.png',$false))){[Lot5Image]::DespillEdge((Join-Path $out $entry[0]),$entry[1])}
}
$metricLines = [System.Collections.Generic.List[string]]::new()
foreach($j in $jobs){$key=if($j[0] -like '*wind*'){@(255,0,255)}else{@(0,255,0)}; $imagePath=Join-Path $out ($j[0]+'.png');$line=[Lot5Image]::Stats($imagePath,$key[0],$key[1],$key[2]);if($j[0] -like '*_far'){$line += " alphaMin=$([Lot5Image]::AlphaMin($imagePath))"};$metricLines.Add($line);Write-Output $line}
foreach($j in $jobs){if($j[0] -like '*_mid'){$type='mid'}elseif($j[0] -like '*floor*'){$type='floor'}elseif($j[0] -like '*ceiling*'){$type='ceiling'}else{continue};$line=[Lot5Image]::Structure((Join-Path $out ($j[0]+'.png')),$type);$metricLines.Add($line);Write-Output $line}
foreach($entry in @(@('jet_bg_wind_mid.png',$true),@('jet_ceiling_wind.png',$true),@('jet_bg_thunder_mid.png',$false),@('jet_ceiling_thunder.png',$false))){$line=[Lot5Image]::EdgeTint((Join-Path $out $entry[0]),$entry[1]);$metricLines.Add($line);Write-Output $line}

function Draw-Asset($g,$path,$x,$y,$w,$h,$flip=$false){$im=[Drawing.Bitmap]::new($path);if($flip){$im.RotateFlip([Drawing.RotateFlipType]::RotateNoneFlipY)};$g.DrawImage($im,[Drawing.Rectangle]::new([int]$x,[int]$y,[int]$w,[int]$h));$im.Dispose()}
function Make-Preview([string]$zone){$canvas=[Drawing.Bitmap]::new(1920,1080);$g=[Drawing.Graphics]::FromImage($canvas);$g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic;$g.Clear([Drawing.Color]::FromArgb(18,16,42));$far=Join-Path $out "jet_bg_${zone}_far.png";$mid=Join-Path $out "jet_bg_${zone}_mid.png";$floor=Join-Path $out "jet_floor_${zone}.png";$ceil=Join-Path $out "jet_ceiling_${zone}.png";Draw-Asset $g $far 0 0 1920 1080;Draw-Asset $g $mid 0 0 1920 1080;Draw-Asset $g $ceil 0 -30 1920 120;Draw-Asset $g $floor 0 910 1920 200
  $char='assets/characters/char_wind_01/frames/run/char_wind_01_run_000.png';Draw-Asset $g $char 420 748 192 192
  # Representative jet obstacles and pickups, identical across both zone previews.
  Draw-Asset $g 'assets/jet/jet_core/jet_core_idle_000.png' 1080 360 70 70
  for($i=0;$i -lt 5;$i++){Draw-Asset $g 'assets/jet/jet_orb/jet_orb_idle_000.png' (1190+$i*52) 465 34 34}
  Draw-Asset $g 'assets/jet/jet_missile/fly_v2/jet_missile_fly_v2_000.png' 1450 625 112 75
  # Sludge beam rotated as a connected bar, with an end cap at both ends.
  $state=$g.Save();$g.TranslateTransform(825,520);$g.RotateTransform(-45);Draw-Asset $g 'assets/jet/jet_beam_body_v2.png' -170 -28 340 56;Draw-Asset $g 'assets/jet/jet_beam_node/pulse/jet_beam_node_pulse_000.png' -202 -43 86 86;Draw-Asset $g 'assets/jet/jet_beam_node/pulse/jet_beam_node_pulse_000.png' 116 -43 86 86;$g.Restore($state)
  if($zone -eq 'wind'){$dragon='assets/jet/jet_dragon/fly/jet_dragon_fly_000.png';Draw-Asset $g $dragon 260 480 260 195;Draw-Asset $g $char 370 478 68 68;Draw-Asset $g 'assets/jet/jet_wind_arrow.png' 1540 350 65 110;Draw-Asset $g 'assets/jet/jet_wind_arrow.png' 1660 400 65 110 $true}else{$block='assets/jet/jet_gate_block.png';$lip='assets/jet/jet_gate_lip/spark/jet_gate_lip_spark_000.png';Draw-Asset $g $block 930 70 70 365;Draw-Asset $g $lip 900 420 130 50;Draw-Asset $g $block 930 795 70 285 $true;Draw-Asset $g $lip 900 770 130 50 $true;Draw-Asset $g 'assets/jet/jet_sweep/hum/jet_sweep_hum_000.png' 1310 385 48 288}
  $brush=[Drawing.SolidBrush]::new([Drawing.Color]::White);$font=[Drawing.Font]::new('Arial',28,[Drawing.FontStyle]::Bold);$g.DrawString($(if($zone -eq 'wind'){'THUNG GIO NGUOC'}else{'HANG SET CAM'}),$font,$brush,[single]30,[single]25);$brush.Dispose();$font.Dispose();$g.Dispose();$canvas.Save((Join-Path $preview "jet_lot5_${zone}_dark.png"),[Drawing.Imaging.ImageFormat]::Png);$canvas.Dispose()
  $gray=[Drawing.Bitmap]::new((Join-Path $preview "jet_lot5_${zone}_dark.png"));$dest=[Drawing.Bitmap]::new(1920,1080);$gg=[Drawing.Graphics]::FromImage($dest);$cm=[Drawing.Imaging.ColorMatrix]::new([single[][]]@([single[]]@(0.299,0.299,0.299,0,0),[single[]]@(0.587,0.587,0.587,0,0),[single[]]@(0.114,0.114,0.114,0,0),[single[]]@(0,0,0,1,0),[single[]]@(0,0,0,0,1)));$ia=[Drawing.Imaging.ImageAttributes]::new();$ia.SetColorMatrix($cm);$gg.DrawImage($gray,[Drawing.Rectangle]::new(0,0,1920,1080),0,0,1920,1080,[Drawing.GraphicsUnit]::Pixel,$ia);$dest.Save((Join-Path $preview "jet_lot5_${zone}_grayscale.png"),[Drawing.Imaging.ImageFormat]::Png);$gg.Dispose();$gray.Dispose();$dest.Dispose()
}
Make-Preview 'wind';Make-Preview 'thunder'
foreach($j in $jobs){$im=[Drawing.Bitmap]::new((Join-Path $out ($j[0]+'.png')));$twice=[Drawing.Bitmap]::new($im.Width*2,$im.Height);$g=[Drawing.Graphics]::FromImage($twice);$g.DrawImage($im,0,0,$im.Width,$im.Height);$g.DrawImage($im,$im.Width,0,$im.Width,$im.Height);$twice.Save((Join-Path $preview ($j[0]+'_tile2.png')),[Drawing.Imaging.ImageFormat]::Png);$g.Dispose();$im.Dispose();$twice.Dispose()}
$metricLines | Set-Content -Encoding utf8 (Join-Path $preview 'jet_lot5_metrics.txt')
